patch:
diff --git a/repro/no-var-tdz.js b/repro/no-var-tdz.js
new file mode 100644
index 0000000..5194ddb
--- /dev/null
+++ b/repro/no-var-tdz.js
@@ -0,0 +1,100 @@
+"use strict";
+
+/*
+ * Repro for "[no-var] Fix causes ReferenceError".
+ * For each case: apply the no-var autofix, then run the original and the
+ * fixed code and compare. A case reproduces the bug when the original runs
+ * fine but the autofixed code throws a ReferenceError (TDZ access).
+ */
+const vm = require("node:vm");
+const { Linter } = require("../lib/api");
+
+const linter = new Linter();
+const config = {
+	languageOptions: { sourceType: "script" },
+	rules: { "no-var": "error" },
+};
+
+const cases = {
+	"report case (reference textually before var)": `
+function a() {
+    console.log(o);
+    var o;
+    return o;
+}
+a();`,
+
+	"hoisted function called indirectly via another hoisted function": `
+function a() {
+    h();
+    var o = 1;
+    function g() { return o; }
+    function h() { return g(); }
+}
+a();`,
+
+	"hoisted function passed as a callback before the var": `
+function a() {
+    [0].forEach(g);
+    var o = 1;
+    function g() { return o; }
+}
+a();`,
+
+	"hoisted function invoked via .call() before the var": `
+function a() {
+    g.call(null);
+    var o = 1;
+    function g() { return o; }
+}
+a();`,
+
+	"hoisted function invoked with new before the var": `
+function a() {
+    new G();
+    var o = 1;
+    function G() { this.v = o; }
+}
+a();`,
+
+	"hoisted function invoked as a tagged template before the var": `
+function a() {
+    g\`\`;
+    var o = 1;
+    function g() { return o; }
+}
+a();`,
+};
+
+function run(code) {
+	try {
+		vm.runInNewContext(code, { console: { log() {} } });
+		return "ok";
+	} catch (e) {
+		return `${e.name}: ${e.message}`;
+	}
+}
+
+let reproduced = 0;
+
+for (const [name, code] of Object.entries(cases)) {
+	const { output, fixed } = linter.verifyAndFix(code, config);
+	const before = run(code);
+	const after = fixed ? run(output) : "(no fix applied)";
+	const bug = fixed && before === "ok" && after.startsWith("ReferenceError");
+
+	if (bug) {
+		reproduced++;
+	}
+	console.log(`=== ${name}`);
+	console.log(`  autofix applied: ${fixed}`);
+	console.log(`  original runs:   ${before}`);
+	console.log(`  fixed runs:      ${after}`);
+	console.log(`  BUG: ${bug ? "YES - autofix introduced a ReferenceError" : "no"}`);
+	if (fixed) {
+		console.log(output.replace(/^/gmu, "    | "));
+	}
+}
+
+console.log(`\n${reproduced} case(s) where the no-var autofix turns working code into a ReferenceError.`);
+process.exitCode = reproduced ? 1 : 0;
